FRAME_FOOTER = '<footer class="pf"><div class="wrap">\n  <div>PTPGE — the open specification of print · <a href="https://creativecommons.org/licenses/by/4.0/" rel="license">CC BY 4.0</a> · <a href="mailto:post@ptpge.org">post@ptpge.org</a> · Public Beta</div>\n  <div class="links"><a href="https://internal.ptpge.org/v1/">API</a><a href="https://mcp.ptpge.org">MCP</a><a href="https://ptpge.org/playground">Playground</a><a href="https://ptpge.org/changelog/">Changelog</a><a href="https://ptpge.org/adopt/">Adopt</a></div>\n</div></footer>\n<script>\n(function(){\n  var c=document.getElementById(\'contours\'); if(!c) return;\n  if(window.matchMedia&&window.matchMedia(\'(prefers-reduced-motion: reduce)\').matches){c.remove();return;}\n  var ctx=c.getContext(\'2d\'), W,H, t=0, dpr=Math.min(window.devicePixelRatio||1,2);\n  // pointer: the field bulges gently around the cursor and eases back (no jank — eased, not tracked)\n  var mx=-1e9,my=-1e9,tx=-1e9,ty=-1e9;\n  addEventListener(\'pointermove\',function(e){tx=e.clientX*dpr;ty=e.clientY*dpr;},{passive:true});\n  addEventListener(\'pointerleave\',function(){tx=-1e9;ty=-1e9;});\n  function size(){W=c.width=innerWidth*dpr;H=c.height=innerHeight*dpr;}\n  size(); addEventListener(\'resize\',size);\n  // smooth value-noise field; contours = iso-lines of the field, drifting slowly\n  var P=[];for(var i=0;i<256;i++)P[i]=i;for(i=255;i>0;i--){var j=(Math.random()*(i+1))|0;var q=P[i];P[i]=P[j];P[j]=q;}P=P.concat(P);\n  function fade(x){return x*x*x*(x*(x*6-15)+10);}function lerp(a,b,x){return a+x*(b-a);}\n  function grad(h,x,y){switch(h&3){case 0:return x+y;case 1:return -x+y;case 2:return x-y;default:return -x-y;}}\n  function noise(x,y){var X=Math.floor(x)&255,Y=Math.floor(y)&255;x-=Math.floor(x);y-=Math.floor(y);var u=fade(x),v=fade(y);\n    var A=P[X]+Y,B=P[X+1]+Y;return lerp(lerp(grad(P[A],x,y),grad(P[B],x-1,y),u),lerp(grad(P[A+1],x,y-1),grad(P[B+1],x-1,y-1),u),v);}\n  function field(x,y){var v=noise(x*0.0016+t*0.00012,y*0.0016)+0.5*noise(x*0.0032-t*0.00008,y*0.0032+t*0.0001);\n    var dx=x-mx,dy=y-my,r2=dx*dx+dy*dy,R=260*dpr; if(r2<R*R){var f=1-Math.sqrt(r2)/R;v+=0.9*f*f;} return v;}\n  var step=10*dpr, levels=14;\n  function draw(){\n    ctx.clearRect(0,0,W,H); ctx.lineWidth=1*dpr; ctx.strokeStyle=document.documentElement.classList.contains(\'dark\')?\'#fff\':\'#000\';\n    var cols=Math.ceil(W/step)+1, rows=Math.ceil(H/step)+1, F=new Float32Array(cols*rows);\n    for(var j=0;j<rows;j++)for(var i=0;i<cols;i++)F[j*cols+i]=field(i*step,j*step);\n    ctx.beginPath();\n    for(var l=0;l<levels;l++){var iso=-1.2+l*(2.4/levels);\n      for(j=0;j<rows-1;j++)for(i=0;i<cols-1;i++){\n        var a=F[j*cols+i],b=F[j*cols+i+1],c2=F[(j+1)*cols+i+1],d=F[(j+1)*cols+i];\n        var idx=(a>iso?8:0)|(b>iso?4:0)|(c2>iso?2:0)|(d>iso?1:0); if(idx===0||idx===15)continue;\n        var x=i*step,y=j*step;\n        function ip(p,q,pv,qv){var s=(iso-pv)/(qv-pv);return [p[0]+(q[0]-p[0])*s,p[1]+(q[1]-p[1])*s];}\n        var top=ip([x,y],[x+step,y],a,b),right=ip([x+step,y],[x+step,y+step],b,c2),bot=ip([x,y+step],[x+step,y+step],d,c2),left=ip([x,y],[x,y+step],a,d);\n        var segs={1:[left,bot],2:[bot,right],3:[left,right],4:[top,right],5:[top,left,bot,right],6:[top,bot],7:[top,left],8:[top,left],9:[top,bot],10:[top,right,bot,left],11:[top,right],12:[left,right],13:[bot,right],14:[left,bot]}[idx];\n        for(var k=0;k<segs.length;k+=2){ctx.moveTo(segs[k][0],segs[k][1]);ctx.lineTo(segs[k+1][0],segs[k+1][1]);}\n      }}\n    ctx.stroke();\n  }\n  var last=0; function loop(now){ mx+= (tx-mx)*0.08; my+=(ty-my)*0.08; if(now-last>40){ t=now; draw(); last=now; } requestAnimationFrame(loop); }\n  requestAnimationFrame(loop);\n})();\n</script>'
